// resolve_user_field resolves the columns of `User`.
fn resolve_user_field(_ context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(user_value((it as UserNode).user, info.field_name)))
}

fn user_value(row models.User, field string) graphql.Value {
	return match field {
		'id' { graphql.Value(row.id.str()) }
		'name' { graphql.Value(string(row.name)) }
		'admin' { graphql.Value(row.admin) }
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `User` list.
fn (q UserQuery) graphql_where(args map[string]graphql.Value) !UserQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...user_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `User` list: `where`, `orderBy`,
// and `limit` and `offset`, bounded by `size`.
fn (q UserQuery) graphql_args(args map[string]graphql.Value, size graphql.PageSize) !UserQuery {
	page := graphql.list_args(args, size)!
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := user_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := page.limit {
		next = next.limit(limit)
	}
	if offset := page.offset {
		next = next.offset(offset)
	}
	return next
}

// user_order returns the orders of an `orderBy` of `User`, and with `with_key`,
// the key last, unless it orders by it already.
fn user_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'i64' }
				keyed = true
			}
			'NAME' {
				orders << load.Order{ column: 'name', desc: desc, typ: 'string' }
			}
			'ADMIN' {
				orders << load.Order{ column: 'admin', desc: desc, typ: 'bool' }
			}
			'CREATED_AT' {
				orders << load.Order{ column: 'created_at', desc: desc, typ: 'time.Time' }
			}
			'POSTS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "posts" AS "t1" WHERE "t1"."author_id" = "t0"."id")', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a UserOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'i64'
		}
	}
	return orders
}

// user_where returns the conditions of a `UserWhereInput`.
fn user_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'not' {
				conds << load.not(load.and(...user_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << user_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...user_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'id' { conds << load.eq('id', gql_i64_id(v)!) }
			'idNEQ' { conds << load.ne('id', gql_i64_id(v)!) }
			'idIn' { conds << load.in_i64s('id', gql_i64s(v)!) }
			'idNotIn' { conds << load.not_in_i64s('id', gql_i64s(v)!) }
			'idGT' { conds << load.gt('id', gql_i64_id(v)!) }
			'idGTE' { conds << load.ge('id', gql_i64_id(v)!) }
			'idLT' { conds << load.lt('id', gql_i64_id(v)!) }
			'idLTE' { conds << load.le('id', gql_i64_id(v)!) }
			'name' { conds << load.eq('name', v.as_string()) }
			'nameNEQ' { conds << load.ne('name', v.as_string()) }
			'nameIn' { conds << load.in_strings('name', gql_strings(v)) }
			'nameNotIn' { conds << load.not_in_strings('name', gql_strings(v)) }
			'nameGT' { conds << load.gt('name', v.as_string()) }
			'nameGTE' { conds << load.ge('name', v.as_string()) }
			'nameLT' { conds << load.lt('name', v.as_string()) }
			'nameLTE' { conds << load.le('name', v.as_string()) }
			'nameContains' { conds << load.contains('name', v.as_string()) }
			'nameHasPrefix' { conds << load.has_prefix('name', v.as_string()) }
			'nameHasSuffix' { conds << load.has_suffix('name', v.as_string()) }
			'nameEqualFold' { conds << load.equal_fold('name', v.as_string()) }
			'nameContainsFold' { conds << load.contains_fold('name', v.as_string()) }
			'admin' { conds << load.eq('admin', v.as_bool()) }
			'adminNEQ' { conds << load.ne('admin', v.as_bool()) }
			'createdAt' { conds << load.eq('created_at', gql_time(v)!) }
			'createdAtNEQ' { conds << load.ne('created_at', gql_time(v)!) }
			'createdAtIn' { conds << load.or(...gql_times(v)!.map(load.eq('created_at', it))) }
			'createdAtNotIn' { conds << load.and(...gql_times(v)!.map(load.ne('created_at', it))) }
			'createdAtGT' { conds << load.gt('created_at', gql_time(v)!) }
			'createdAtGTE' { conds << load.ge('created_at', gql_time(v)!) }
			'createdAtLT' { conds << load.lt('created_at', gql_time(v)!) }
			'createdAtLTE' { conds << load.le('created_at', gql_time(v)!) }
			'hasPosts' {
				conds << if v.as_bool() { user_has_posts() } else { load.not(user_has_posts()) }
			}
			'hasPostsWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << post_where(item.as_map())!
				}
				conds << user_has_posts_with(...all)
			}
			else {}
		}
	}
	return conds
}

// user_count_posts counts the `posts` of each of `rows` that `sub` keeps, by the
// row's key.
fn user_count_posts(g Graph, rows []models.User, sub PostQuery) !map[string]int {
	conds := g.client.prepare_edge_query('posts', sub.query)!.conds
	return load.count_each(g.client.conn, 'posts', 'author_id', rows.map(it.id.str()),
		.i64, load.Query{
			conds: conds
		})
}

